(()=>{'use strict';
const B='https://woongbi-quote-api.woongbts.workers.dev';let C=null,P=null;
const num=v=>Number.isFinite(Number(v))?Number(v):0;
async function post(body){let last;for(let i=0;i<3;i++){const ctl=typeof AbortController!=='undefined'?new AbortController():null,t=ctl?setTimeout(()=>ctl.abort(),8000):0;try{const r=await fetch(B+'/quote/internet',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:ctl?.signal});const d=await r.json().catch(()=>({}));if(r.ok&&d?.ok===true)return d;last=new Error(d?.error||('internet-api-'+r.status))}catch(e){last=e}finally{if(t)clearTimeout(t)}if(i<2)await new Promise(r=>setTimeout(r,500*(i+1)))}throw last||new Error('internet-api-unavailable')}
function normalizeCatalog(c){if(!c||typeof c!=='object')return c;const out={...c};if(Array.isArray(c.settop_products))out.settop_products=c.settop_products.map(x=>{if(x?.provider_id==='KT')return{...x,name:'기가지니 A 셋톱',product_key:'SETTOP_GIGAGENIEA',monthly_fee:3300};if(x?.provider_id==='SKB'||x?.provider_id==='SKTNET')return{...x,name:'스마트3 셋톱',product_key:'SETTOP_SMART3',monthly_fee:4400};if(x?.provider_id==='LGU+')return{...x,name:'4K UHD4 셋톱',product_key:'SETTOP_4K_UHD4',monthly_fee:4400};return x});return out}
function findInternet(id){return(C?.internet_products||[]).find(x=>x.id===id)||null}
function findTv(id){return(C?.tv_products||[]).find(x=>x.id===id)||null}
function mobileSelected(id){return!!id&&id!=='none'}
function normalizeOptions(options,internet_product_id,tv_product_id='none'){if(!options||typeof options!=='object')return options;const p=findInternet(internet_product_id),hasTv=!!tv_product_id&&tv_product_id!=='none',out={...options,wired:Array.isArray(options.wired)?options.wired.map(x=>({...x})):[],mobile:Array.isArray(options.mobile)?options.mobile.map(x=>({...x})):[]};if(!p)return out;const speed=Number(p.speed_mbps),provider=p.provider_id;if((provider==='SKB'||provider==='SKTNET')&&(speed===100||speed===500)){const discount=hasTv?(speed===100?5500:6600):(speed===100?4400:11000);out.mobile=out.mobile.map(x=>({...x,discount,name:`요즘가족결합 · ${hasTv?'인터넷+TV':'인터넷'} ${discount.toLocaleString('ko-KR')}원 할인`,notes:hasTv?`인터넷+TV 동시 이용 기준 청구 할인 ${discount.toLocaleString('ko-KR')}원 · 휴대폰 요금 할인은 별도`:`인터넷 단독 기준 청구 할인 ${discount.toLocaleString('ko-KR')}원 · 휴대폰 요금 할인은 별도`}))}
if(provider==='LGU+'&&hasTv&&speed===100){const seed=out.mobile[0]||{};out.mobile=[{...seed,id:'LGU_100_TV_EASY_1',discount:5500,name:'참 쉬운 가족결합 · 모바일 1회선 5,500원 할인',notes:'100M 인터넷+TV 실속형 · 4K UHD4 셋톱 기준 · 모바일 1회선 결합'}]}
if(provider==='KT'&&hasTv&&speed===100){const seed=out.mobile[0]||{};out.mobile=[{...seed,id:'KT_100_TV_MOBILE_UNDER22',discount:1650,name:'모바일 월정액 22,000원 미만 · 1,650원 할인',notes:'100M 인터넷+TV · 기가지니 A 기준 · 모바일 월정액 22,000원 미만'},{...seed,id:'KT_100_TV_MOBILE_22',discount:3300,name:'모바일 월정액 22,000원 이상 · 3,300원 할인',notes:'100M 인터넷+TV · 기가지니 A 기준 · 모바일 월정액 22,000원 이상~64,900원 미만'},{...seed,id:'KT_100_TV_MOBILE_649',discount:5500,name:'모바일 월정액 64,900원 이상 · 5,500원 할인',notes:'100M 인터넷+TV · 기가지니 A 기준 · 모바일 월정액 64,900원 이상'}]}else if(provider==='KT'&&speed===500&&hasTv&&out.mobile.length){const first={...out.mobile[0],discount:5500,name:'모바일 결합 · 인터넷+TV 5,500원 할인',notes:'500M 인터넷+TV · 기가지니 A 셋톱 기준 청구 할인 5,500원'};out.mobile=[first]}
return out}
function setDiscounts(r,automatic,mobile){r.automatic_discount=Math.max(0,num(automatic));r.wired_discount=0;r.mobile_discount=Math.max(0,num(mobile));r.applied_discount=r.automatic_discount+r.mobile_discount;r.total=Math.max(0,num(r.base)-r.applied_discount);return r}
function normalizeQuote(q,args={}){if(!q||q.known!==true)return q;const p=findInternet(args.internet_product_id),tv=findTv(args.tv_product_id),hasTv=!!tv&&args.tv_product_id!=='none',count=Math.max(1,Number(args.tv_count)||1);if(!p)return q;const provider=p.provider_id,speed=Number(p.speed_mbps),hasMobile=mobileSelected(args.mobile_bundle_id);let r={...q};
if((provider==='SKB'||provider==='SKTNET')&&(speed===100||speed===500)){
  if(!hasTv){const md=hasMobile?(speed===100?4400:11000):0;r.base=num(p.monthly_fee)||num(q.base);r.internet_display=r.base;r.tv_display=0;r.extra_tv=0;setDiscounts(r,0,md)}
  else if(count===1){const stb=4400,intAuto=speed===100?2200:6600,tvAuto=speed===100?0:1100,auto=intAuto+tvAuto,md=hasMobile?(speed===100?5500:6600):0;r.base=num(p.monthly_fee)+num(tv.monthly_fee)+stb;r.internet_display=Math.max(0,num(p.monthly_fee)-intAuto);r.tv_display=Math.max(0,num(tv.monthly_fee)-tvAuto)+stb;r.extra_tv=0;r.settop_fee=stb;setDiscounts(r,auto,md)}
}
if(provider==='LGU+'&&hasTv&&count===1&&speed===100&&(String(tv.id||'').includes('TV_ECONOMY_PACK')||String(tv.name||'').includes('실속형'))){const stb=4400,base=41800,auto=2200,md=hasMobile?5500:0;r.base=base;r.internet_display=19800;r.tv_display=19800;r.extra_tv=0;r.settop_fee=stb;setDiscounts(r,auto,md)}
if(provider==='KT'&&hasTv&&count===1){const stb=3300,intAuto=5500,tvAuto=2640,auto=intAuto+tvAuto;let md=0;if(hasMobile&&speed===100)md=args.mobile_bundle_id==='KT_100_TV_MOBILE_UNDER22'?1650:args.mobile_bundle_id==='KT_100_TV_MOBILE_22'?3300:args.mobile_bundle_id==='KT_100_TV_MOBILE_649'?5500:num(q.mobile_discount);else if(hasMobile&&speed===500)md=5500;else md=num(q.mobile_discount);r.base=num(p.monthly_fee)+num(tv.monthly_fee)+stb;r.internet_display=Math.max(0,num(p.monthly_fee)-intAuto);r.tv_display=Math.max(0,num(tv.monthly_fee)-tvAuto)+stb;r.extra_tv=0;r.settop_fee=stb;setDiscounts(r,auto,md)}
return r}
async function loadCatalog(){if(C)return C;if(P)return P;P=post({mode:'catalog'}).then(d=>{C=normalizeCatalog(d.catalog);document.documentElement.dataset.internetApi='ready';window.dispatchEvent(new CustomEvent('woongbi:internet-api-ready',{detail:C}));return C}).catch(e=>{document.documentElement.dataset.internetApi='unavailable';window.dispatchEvent(new CustomEvent('woongbi:internet-api-unavailable'));throw e}).finally(()=>{P=null});return P}
async function options(internet_product_id,tv_product_id='none'){if(!C)await loadCatalog();const data=await post({mode:'options',internet_product_id,tv_product_id});return normalizeOptions(data.options,internet_product_id,tv_product_id)}
async function quote({internet_product_id,tv_product_id='none',tv_count=1,wired_bundle_id='none',mobile_bundle_id='none'}){if(!C)await loadCatalog();const args={internet_product_id,tv_product_id,tv_count:Number(tv_count)||1,wired_bundle_id,mobile_bundle_id},data=await post(args);return normalizeQuote(data.quote,args)}
async function compare({speed_mbps=500,include_tv=false,tv_count=1}){if(!C)await loadCatalog();const count=Number(tv_count)||1,data=await post({mode:'compare',speed_mbps:Number(speed_mbps)||500,include_tv:Boolean(include_tv),tv_count:count});return(data.items||[]).map(item=>{const internet=item?.internet,tv=item?.tv,args={internet_product_id:internet?.id,tv_product_id:tv?.id||'none',tv_count:count,wired_bundle_id:'auto-combo',mobile_bundle_id:'none'};return{...item,quote:normalizeQuote(item?.quote,args)}})}
window.WoongbiInternetApi={loadCatalog,options,quote,compare};
})();
